    ExpenseTrackerApiSdkConfig config = ExpenseTrackerApiSdkConfig.builder()
			.accessToken("YOUR_ACCESS_TOKEN")
			.build();

    ExpenseTrackerApiSdk expenseTrackerApiSdk = new ExpenseTrackerApiSdk(config);


